CREATE TABLE IF NOT EXISTS "tms_carrier" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" varchar(255),
    "code" varchar(255),
    "service_type" int,
    "contact_person" varchar(255),
    "contact_phone" varchar(255),
    "qualification_no" varchar(255),
    "rating" int,
    "status" int,
    "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "tms_driver" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" varchar(255),
    "phone" varchar(255),
    "license_no" varchar(255),
    "license_type" varchar(255),
    "carrier_id" bigint,
    "status" int,
    "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "tms_fleet_operation" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "vehicle_id" bigint,
    "operation_date" date,
    "mileage" decimal(20,2),
    "fuel_consumption" decimal(20,2),
    "fuel_cost" decimal(20,2),
    "maintenance_cost" decimal(20,2),
    "insurance_cost" decimal(20,2),
    "inspection_cost" decimal(20,2),
    "revenue" decimal(20,2),
    "total_cost" decimal(20,2),
    "profit" decimal(20,2),
    "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "tms_freight" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "no" varchar(255),
    "shipment_id" bigint,
    "carrier_id" bigint,
    "billing_method" int,
    "billing_quantity" decimal(20,2),
    "unit_price" decimal(20,2),
    "surcharge" decimal(20,2),
    "discount_amount" decimal(20,2),
    "total_amount" decimal(20,2),
    "status" int,
    "auditor" varchar(255),
    "audit_time" timestamp,
    "settle_time" timestamp,
    "reject_reason" varchar(255),
    "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "tms_freight_reconciliation" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "no" varchar(255),
    "carrier_id" bigint,
    "period_start" date,
    "period_end" date,
    "system_amount" decimal(20,2),
    "carrier_amount" decimal(20,2),
    "diff_amount" decimal(20,2),
    "status" int,
    "reconciler_id" bigint,
    "reconcile_time" varchar(255),
    "confirmer_id" bigint,
    "confirm_time" varchar(255),
    "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "tms_gps_position" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "vehicle_id" bigint,
    "shipment_id" bigint,
    "longitude" decimal(20,2),
    "latitude" decimal(20,2),
    "speed" decimal(20,2),
    "direction" decimal(20,2),
    "report_time" timestamp,
    "location_desc" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "tms_shipment" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "no" varchar(255),
    "carrier_id" bigint,
    "vehicle_id" bigint,
    "driver_id" bigint,
    "origin_address" varchar(255),
    "destination_address" varchar(255),
    "shipment_type" int,
    "source_order_no" varchar(255),
    "total_quantity" decimal(20,2),
    "total_weight" decimal(20,2),
    "total_volume" decimal(20,2),
    "freight_amount" decimal(20,2),
    "departure_time" timestamp,
    "estimated_arrival_time" timestamp,
    "actual_arrival_time" timestamp,
    "status" int,
    "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "tms_shipment_stop" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "shipment_id" bigint,
    "sequence_no" int,
    "address" varchar(255),
    "arrival_time" timestamp,
    "departure_time" timestamp,
    "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "tms_tracking_event" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "shipment_id" bigint,
    "event_type" int,
    "event_time" timestamp,
    "location" varchar(255),
    "longitude" decimal(20,2),
    "latitude" decimal(20,2),
    "description" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "tms_vehicle" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "plate_no" varchar(255),
    "vehicle_type" varchar(255),
    "carrier_id" bigint,
    "load_capacity" decimal(20,2),
    "volume" decimal(20,2),
    "driver_user_id" bigint,
    "status" int,
    "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
);
